import{readFileSync,writeFileSync,existsSync}from'node:fs';import{productionEnvironment,productionPsql}from'../scripts/lib/production-database.mjs';import{ownPhoneTab}from'./samsung-cdp-20261024.mjs';import{syntheticName}from'../scripts/lib/capacity-load.mjs';
const negative=process.argv[2]==='--dry-run-guard',guardOnly=negative||process.argv[2]==='--dry-run-valid';const out=guardOnly?(negative?'.verification/owned-natalia-journeys-cleanup-guard-probe-v2-20261024.json':'.verification/owned-natalia-journeys-cleanup-valid-probe-20261024.json'):'.verification/owned-natalia-journeys-cleanup-20261024.json';if(existsSync(out))throw Error('CLEANUP_RECEIPT_EXISTS_INSPECT_FIRST');const v2=JSON.parse(readFileSync('.verification/samsung-natalia-production-journey-v2-20261024.json')),v3=JSON.parse(readFileSync('.verification/samsung-natalia-production-journey-v3-20261024.json'));if(!v2.cancelled||!v2.recoveryWithoutDuplicate||!v3.passed||!v3.cancelled||!v3.recoveryWithoutDuplicate)throw Error('JOURNEY_EVIDENCE_INCOMPLETE');
const specs=[[v2,'5491177140024'],[v3,'5491177140025']].map(([r,phone])=>({appointmentId:r.appointmentId,patientId:r.patientId,phone,name:syntheticName('Paciente Sintetico Natalia','+'+phone)}));if(specs.some(s=>!/^[0-9a-f-]{36}$/.test(s.appointmentId)||!/^[0-9a-f-]{36}$/.test(s.patientId))||new Set(specs.map(s=>s.appointmentId)).size!==2||new Set(specs.map(s=>s.patientId)).size!==2)throw Error('OWN_TARGETS_NOT_EXACT');const business='cdef6981-9dfb-4ae8-b862-4a61c07b299d',{database}=productionEnvironment(process.cwd());const lit=s=>"'"+s.replaceAll("'","''")+"'",appointments=specs.map(s=>lit(s.appointmentId)).join(','),patients=specs.map(s=>lit(s.patientId)).join(',');
const core=()=>JSON.parse(productionPsql(database,"begin transaction read only;select json_build_object('businesses',(select count(*)from public.businesses),'owners',(select count(*)from auth.users),'patients',(select count(*)from public.patients),'appointments',(select count(*)from public.appointments),'calendarConnections',(select count(*)from public.google_calendar_connections),'calendarEvents',(select count(*)from public.appointment_google_calendar_events),'storedObjects',(select count(*)from storage.objects));commit;",{application:'cita_suite_owned_natalia_cleanup_readback'}).trim());const r={at:new Date().toISOString(),scope:'Only two explicitly synthetic Natalia journey appointments and their two newly created patients. Never delete Natalia business, members or Auth owners; preserve clinical/files/history and shared phone device.',targets:specs.map(({appointmentId,patientId})=>({appointmentId,patientId})),before:core(),status:'preflight'};writeFileSync(out,JSON.stringify(r,null,2)+'\n',{mode:0o600,flag:'wx'});
if(!guardOnly){let phone;try{phone=await ownPhoneTab();r.phoneNotificationCleanup=await phone.evaluate(`(async()=>{const reg=await navigator.serviceWorker.getRegistration('/');if(!reg)return{closed:0};const all=await reg.getNotifications();const ids=${JSON.stringify(specs.map(s=>s.appointmentId))};const own=all.filter(x=>ids.some(id=>(x.tag??'').startsWith('turno-'+id+'-')));for(const n of own)n.close();return{closed:own.length,operatorAction:true,subscriptionUntouched:true}})()`);}catch{r.phoneNotificationCleanup={confirmed:false};}finally{phone?.close();}}
const guard=specs.map(s=>`if not exists(select 1 from public.appointments a join public.patients p on p.id=a.patient_id and p.business_id=a.business_id join public.appointment_booking_contexts c on c.appointment_id=a.id and c.business_id=a.business_id where a.id=${lit(s.appointmentId)} and a.patient_id=${lit(s.patientId)} and a.business_id='${business}' and a.status='cancelled' and a.source='public_booking' and c.theme_snapshot='natalia' and c.integration_id='89b2ad66-845b-41e2-87e7-cd99abc1c168' and p.phone=${lit(s.phone)} and p.full_name=${lit(s.name)} and p.created_at=a.created_at and a.created_at>='2026-10-24T12:43:00Z' and a.created_at<'2026-10-25T00:00:00Z')then raise exception 'OWN_NATALIA_IDENTITY_CHANGED';end if;`).join('\n');
const sql=`begin;select id from public.appointments where id in(${appointments}) for update;select id from public.patients where id in(${patients}) for update;do $$begin ${guard}
if(select count(*)from public.appointments where patient_id in(${patients}))<>2
or exists(select 1 from public.clinical_entries where patient_id in(${patients}))
or exists(select 1 from public.patient_radiographs where patient_id in(${patients}))
or exists(select 1 from public.follow_ups where patient_id in(${patients}))
or exists(select 1 from public.appointment_google_calendar_events where appointment_id in(${appointments}))
or exists(select 1 from public.appointment_intake_responses where patient_id in(${patients})and(appointment_id not in(${appointments})or business_id<>'${business}'))
or exists(select 1 from public.appointment_intake_submissions where patient_id in(${patients})and(appointment_id not in(${appointments})or business_id<>'${business}'))
then raise exception 'OWN_NATALIA_SCOPE_CHANGED';end if;end $$;
delete from public.public_booking_attempts where business_id='${business}'and appointment_id in(${appointments});
delete from public.appointment_intake_submissions where business_id='${business}'and appointment_id in(${appointments})and patient_id in(${patients});
delete from public.appointment_intake_responses where business_id='${business}'and appointment_id in(${appointments})and patient_id in(${patients});
delete from public.appointments where business_id='${business}'and id in(${appointments});
delete from public.patients where business_id='${business}'and id in(${patients});commit;`;
if(guardOnly){let probe=sql.slice(0,sql.indexOf('delete from public.public_booking_attempts'))+'rollback;';probe=probe.replace(/^begin;/,'begin transaction read only;').replaceAll(' for update;',';');if(negative){const injected=probe.replace("p.phone='5491177140024'","p.phone='0000000000000'");if(injected===probe)throw Error('NEGATIVE_PROBE_NOT_INJECTED');probe=injected;}let success=false,rejected=false;try{productionPsql(database,probe,{application:'cita_suite_owned_natalia_guard_probe'});success=true;}catch(e){rejected=String(e.message).includes('OWN_NATALIA_IDENTITY_CHANGED');r.probeFailureCategory=rejected?'owned-identity-guard':String(e.message).includes('read-only transaction')?'readonly-probe-limitation':'other-query-failure';}r.after=core();r.wrongPhoneRejectedBeforeMutation=rejected;r.validIdentityAccepted=success;r.readonlyTransaction=true;r.deletionsRemovedFromProbe=true;r.passed=(negative?rejected:success)&&JSON.stringify(r.after)===JSON.stringify(r.before);r.status=r.passed?(negative?'guard-rejected-wrong-identity-readonly-no-mutation':'guard-accepted-exact-owned-identities-readonly-no-mutation'):'guard-probe-failed';writeFileSync(out,JSON.stringify(r,null,2)+'\n',{mode:0o600});console.log({status:r.status,passed:r.passed,probeFailureCategory:r.probeFailureCategory});if(!r.passed)process.exitCode=1;process.exit();}
productionPsql(database,sql,{application:'cita_suite_owned_natalia_cleanup'});r.after=core();for(const k of['businesses','owners','calendarConnections','calendarEvents','storedObjects'])if(r.before[k]!==r.after[k])throw Error('UNRELATED_COUNTS_CHANGED');if(r.before.patients-r.after.patients!==2||r.before.appointments-r.after.appointments!==2)throw Error('OWN_CLEANUP_COUNT_DIFFERS');r.status='cleaned-two-owned-appointments-and-patients';r.finishedAt=new Date().toISOString();r.passed=true;writeFileSync(out,JSON.stringify(r,null,2)+'\n',{mode:0o600});console.log({status:r.status,passed:r.passed,businessAndOwnersPreserved:true});
